import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Arora 2021 - LiLSX PSA'
sim.info.description = '4-step Skarstrom PSA, air separation to O2, LiLSX adsorbent (Table 4)'
sim.info.author = 'Arora & Hasan (2021)'

# ---- fluid --------------------------------------------------------------------
sim.add_component('Oxygen')
sim.add_component('Nitrogen')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0

# ---- adsorbents -----------------------------------------------------------------
ads_lix_zeolite = sim.add_adsorbent('LiX Zeolite', solid_density=1200.0, heat_capacity=1172.0, thermal_conductivity=0.15, particle_void_fraction=0.33)
ads_lix_zeolite.set_isotherm('dual_site_langmuir_p', {
    'Oxygen': {'m1': 1.5, 'b1': 1e-10, 'q1': 21774.6, 'm2': 0.6075, 'b2': 1e-10, 'q2': 24624.1},
    'Nitrogen': {'m1': 1.5, 'b1': 1e-10, 'q1': 29195.0, 'm2': 1.5, 'b2': 1e-10, 'q2': 26260.5},
}, components=['Oxygen', 'Nitrogen'])
ads_lix_zeolite.set_rate_model('Oxygen', 'ldf', 'constant', k=104.07)
ads_lix_zeolite.set_rate_model('Nitrogen', 'ldf', 'constant', k=42.84)
ads_lix_zeolite.heat_of_adsorption['Oxygen'] = 13221.44
ads_lix_zeolite.heat_of_adsorption['Nitrogen'] = 23430.4
ads_lilsx_zeolite = sim.add_adsorbent('LiLSX Zeolite', solid_density=1035.0, heat_capacity=1172.0, thermal_conductivity=0.15, particle_void_fraction=0.33)
ads_lilsx_zeolite.set_isotherm('dual_site_langmuir_p', {
    'Oxygen': {'m1': 1.5, 'b1': 1e-10, 'q1': 19606.9, 'm2': 1.5, 'b2': 1e-10, 'q2': 22906.2},
    'Nitrogen': {'m1': 1.5, 'b1': 1e-10, 'q1': 27923.9, 'm2': 0.6613, 'b2': 1e-10, 'q2': 27923.9},
}, components=['Oxygen', 'Nitrogen'])
ads_lilsx_zeolite.set_rate_model('Oxygen', 'ldf', 'constant', k=104.07)
ads_lilsx_zeolite.set_rate_model('Nitrogen', 'ldf', 'constant', k=42.84)
ads_lilsx_zeolite.heat_of_adsorption['Oxygen'] = 14661.44
ads_lilsx_zeolite.heat_of_adsorption['Nitrogen'] = 25451.65
ads_zeolite_5a = sim.add_adsorbent('Zeolite 5A', solid_density=1160.0, heat_capacity=1338.9, thermal_conductivity=0.15, particle_void_fraction=0.65)
ads_zeolite_5a.set_isotherm('dual_site_langmuir_p', {
    'Oxygen': {'m1': 1.5, 'b1': 1e-10, 'q1': 22312.1, 'm2': 1.5, 'b2': 1e-10, 'q2': 22312.1},
    'Nitrogen': {'m1': 1.5, 'b1': 1e-10, 'q1': 26140.8, 'm2': 1.5, 'b2': 1e-10, 'q2': 23284.3},
}, components=['Oxygen', 'Nitrogen'])
ads_zeolite_5a.set_rate_model('Oxygen', 'ldf', 'constant', k=12.07)
ads_zeolite_5a.set_rate_model('Nitrogen', 'ldf', 'constant', k=4.02)
ads_zeolite_5a.heat_of_adsorption['Oxygen'] = 13221.44
ads_zeolite_5a.heat_of_adsorption['Nitrogen'] = 22886.48

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.1)
sim.bed.ambient_temperature = 298.0
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
sim.bed.top_void.enabled = False
sim.bed.top_void.volume = 0.0001
sim.bed.top_void.resistance_coefficient = 0.0
sim.wall.set_material('ss316l', density=7800.0, heat_capacity=537.0, thermal_conductivity=16.2)
sim.wall.thickness = 0.0175
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_lilsx_zeolite = sim.add_layer('LiLSX Zeolite', composition={'LiLSX Zeolite': 1.0}, momentum='kozeny_carman', length=0.127, cells=30, bed_void_fraction=0.35, particle_diameter=0.035)
layer_lilsx_zeolite.set_dispersion('constant', dispersion_coefficient=0.0)
layer_lilsx_zeolite.set_heat_dispersion('constant', heat_dispersion_coefficient=0.29)
layer_lilsx_zeolite.set_internal_heat_transfer('constant', internal_htc=70.0)
layer_lilsx_zeolite.set_external_heat_transfer('constant', external_htc=70.0)

# ---- initial conditions --------------------------------------------------------
sim.initial_conditions.pressure = 350000.0
sim.initial_conditions.temperature = 298.0
sim.initial_conditions.wall_temperature = 298.0
sim.initial_conditions.velocity = 0.0
sim.initial_conditions.y['Nitrogen'] = 0.79
sim.initial_conditions.y['Oxygen'] = 0.21

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 50
sim.cycle.step_time_mode = 0
production = sim.add_step('Production', time=3.0)
production.bottom.set_streams('inlet', [
    sk.Stream('', flow=sk.molar_flow(0.23), y={'Nitrogen': 0.79, 'Oxygen': 0.21}, temperature=298.0),
])
production.top.set_pressure('outlet', 350000.0, y={'Nitrogen': 0.15000000000000002, 'Oxygen': 0.85}, temperature=293.0)
depressurization = sim.add_step('Depressurization', time=1.0)
depressurization.bottom.set_pressure('outlet', sk.linear(100000.0), y={'Nitrogen': 0.15000000000000002, 'Oxygen': 0.85}, temperature=293.0)
depressurization.top.set_closed()
purge = sim.add_step('Purge', time=1.4)
purge.bottom.set_pressure('outlet', 100000.0, y={'Nitrogen': 0.79, 'Oxygen': 0.21}, temperature=293.0)
purge.top.set_streams('inlet', [
    sk.Stream('', flow=sk.molar_flow(0.12945714285714285), y={'Nitrogen': 0.15000000000000002, 'Oxygen': 0.85}, temperature=298.0),
])
pressurization = sim.add_step('Pressurization', time=1.0)
pressurization.bottom.set_closed()
pressurization.top.set_pressure('inlet', sk.linear(350000.0), y={'Nitrogen': 0.15000000000000002, 'Oxygen': 0.85}, temperature=298.0)
sim.kpi.track('Oxygen', feed=[production.bottom[0]], product=[production.top, purge.top[0], pressurization.top])

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
sim.settings.min_step = 1e-15
sim.settings.max_step = 0.01
sim.settings.reltol = 1e-06
sim.settings.nonlin_conv_coef = 0.1
sim.settings.max_order = 5
sim.settings.max_nonlin_iters = 15
sim.settings.max_conv_fails = 200
sim.settings.max_err_test_fails = 40
sim.settings.max_num_steps = 100000
sim.settings.max_iters_per_step = 50000
sim.settings.advection_scheme = 0
sim.settings.max_cycles_to_keep = 10
sim.settings.max_log_points_per_step = 200
sim.settings.acceleration_method = 0
sim.css.method = 0
sim.css.min_cycles = 5
sim.css.molar_absolute_tolerance = 0.0001
sim.css.molar_relative_tolerance = 0.0001
sim.css.mass_balance_tolerance = 0.005
sim.energy_balance.energy_balance_mode = 0
sim.energy_balance.isothermal_use_initial_temperature = True
sim.energy_balance.isothermal_temperature = 298.15


if __name__ == "__main__":
    import sys

    result = sim.run(cycles=int(sys.argv[1]) if len(sys.argv) > 1 else None)
    print(result.status, f"after {result.cycles_run} cycles")
    for k in sim.kpis(cycle=-1):
        print(f"{k.component}: purity {k.purity:.4f}, recovery {k.recovery:.4f}")
